import com.android.tools.smali.dexlib2.*;
import com.android.tools.smali.dexlib2.dexbacked.*;
import com.android.tools.smali.dexlib2.iface.*;
import com.android.tools.smali.dexlib2.iface.instruction.*;
import com.android.tools.smali.dexlib2.iface.reference.*;
import java.util.*;import java.util.zip.*;
public class VerifyViewerFilterHooks {
 static Map<String,ClassDef> load(String file)throws Exception{Map<String,ClassDef> all=new HashMap<>();try(var z=new ZipFile(file)){for(var e:Collections.list(z.entries()))if(e.getName().matches("classes[0-9]*\\.dex"))try(var in=new java.io.BufferedInputStream(z.getInputStream(e))){for(var c:DexBackedDexFile.fromInputStream(Opcodes.getDefault(),in).getClasses())all.put(c.getType(),c);}}return all;}
 static Method method(Map<String,ClassDef> all,String type,String name,List<String> args){for(var m:all.get(type).getMethods())if(m.getName().equals(name)&&m.getParameterTypes().equals(args))return m;throw new AssertionError(name);}
 static List<Instruction> code(Method m){var r=new ArrayList<Instruction>();m.getImplementation().getInstructions().forEach(r::add);return r;}
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static void same(Method before,Method after){check(before.getImplementation().getRegisterCount()==after.getImplementation().getRegisterCount(),"registers");var a=code(before);var b=code(after);check(a.size()==b.size(),"body length");for(int n=0;n<a.size();n++){var x=a.get(n);var y=b.get(n);check(x.getOpcode()==y.getOpcode(),"opcode "+n);if(x instanceof ReferenceInstruction r)check(r.getReference().toString().equals(((ReferenceInstruction)y).getReference().toString()),"reference");if(x instanceof OneRegisterInstruction r)check(r.getRegisterA()==((OneRegisterInstruction)y).getRegisterA(),"A");if(x instanceof TwoRegisterInstruction r)check(r.getRegisterB()==((TwoRegisterInstruction)y).getRegisterB(),"B");if(x instanceof OffsetInstruction r)check(r.getCodeOffset()==((OffsetInstruction)y).getCodeOffset(),"offset");}}
 public static void main(String[] args)throws Exception{var old=load(args[0]);var patched=load(args[1]);if(args[2].equals("242")){
  same(method(old,"Lo/VN10;","G",List.of("Lo/VN10;")),method(patched,"Lo/VN10;","haiagaruNativeImageClose",List.of("Lo/VN10;")));
  var wrapper=method(patched,"Lo/VN10;","G",List.of("Lo/VN10;"));var c=code(wrapper);check(wrapper.getImplementation().getRegisterCount()==2,"wrapper registers");check(c.size()==5,"bounded guard");check(((MethodReference)((ReferenceInstruction)c.get(0)).getReference()).getName().equals("getFragmentManager"),"nullable accessor");check(c.get(2).getOpcode()==Opcode.IF_EQZ&&((OffsetInstruction)c.get(2)).getCodeOffset()==5,"skip detached callback");check(((MethodReference)((ReferenceInstruction)c.get(3)).getReference()).getName().equals("haiagaruNativeImageClose"),"original delegate");
  System.out.println("PASS 242 detached guard and full original close body/registers/branches");
 }else if(args[2].equals("191")){
  var before=method(old,"Lo/m9ExternalSyntheticLambda1;","c",List.of("Z"));var after=method(patched,"Lo/m9ExternalSyntheticLambda1;","c",List.of("Z"));check(before.getImplementation().getRegisterCount()==after.getImplementation().getRegisterCount(),"filter registers");var c=code(after);int found=0;for(int n=0;n<c.size();n++)if(c.get(n) instanceof ReferenceInstruction r&&r.getReference() instanceof MethodReference m&&m.getName().equals("videoFilterMatch")){found++;var call=(RegisterRangeInstruction)c.get(n);check(call.getStartRegister()==25&&call.getRegisterCount()==2,"URL and native result");check(c.get(n-1).getOpcode()==Opcode.MOVE_RESULT_OBJECT&&c.get(n+1).getOpcode()==Opcode.MOVE_RESULT&&c.get(n+2).getOpcode()==Opcode.IF_EQZ,"bounded native predicate");check(((MethodReference)((ReferenceInstruction)c.get(n-2)).getReference()).getDefiningClass().equals("Lo/r0ExternalSyntheticLambda3;"),"native matcher retained");}check(found==1,"one scoped filter hook");int urls=0;for(int n=0;n<c.size();n++)if(c.get(n) instanceof ReferenceInstruction r&&r.getReference() instanceof MethodReference m&&m.getName().equals("videoFilterUrls")){urls++;var call=(RegisterRangeInstruction)c.get(n);check(call.getStartRegister()==25&&call.getRegisterCount()==2,"URL supplement scratch words");check(((TwoRegisterInstruction)c.get(n-2)).getRegisterA()==25&&((TwoRegisterInstruction)c.get(n-2)).getRegisterB()==7,"same response");check(((TwoRegisterInstruction)c.get(n-1)).getRegisterA()==26&&((TwoRegisterInstruction)c.get(n-1)).getRegisterB()==2,"original URLs");check(c.get(n+1).getOpcode()==Opcode.MOVE_RESULT_OBJECT&&((OneRegisterInstruction)c.get(n+1)).getRegisterA()==2,"replace URL loop input only");}check(urls==1,"one scoped URL supplement");System.out.println("PASS 191 native video filter register/result/branch scope");
 }}
}
